#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

const int MAXN = 250010;
long long factorial[MAXN], inv_factorial[MAXN];
long long dynamic[30][MAXN];
int bits[MAXN];
long long total, limit, modulus;

long long combination(int a, int b) {
    return factorial[a] * inv_factorial[a - b] % modulus * inv_factorial[b] % modulus;
}

void add_mod(long long &x, long long y) {
    x += y;
    if (x >= modulus) x -= modulus;
}

int main() {
    cin >> total >> limit >> modulus;
    inv_factorial[0] = factorial[0] = 1;
    inv_factorial[1] = factorial[1] = 1;
    for (int i = 2; i <= total; i++) {
        int q = modulus / i;
        int r = modulus - i * q;
        factorial[i] = factorial[i - 1] * i % modulus;
        inv_factorial[i] = modulus - (long long)q * inv_factorial[r] % modulus;
    }
    for (int i = 2; i <= total; i++) {
        inv_factorial[i] = inv_factorial[i - 1] * inv_factorial[i] % modulus;
    }
    long long answer = 1;
    for (int i = 1; i <= total; i++) answer = answer * limit % modulus;
    for (int i = 1; i <= total; i++) bits[i] = bits[i >> 1] + (i & 1);
    if (total & 1) {
        cout << answer << endl;
        return 0;
    }
    dynamic[0][0] = 1;
    int max_bits = min((long long)bits[total], limit);
    for (int i = 0; i < max_bits; i++) {
        for (int j = 0; j < total; j++) {
            if (dynamic[i][j] == 0) continue;
            int mask = total ^ j;
            for (int k = mask, r; k > j; k = (k - 1) & mask) {
                r = k | j;
                add_mod(dynamic[i + 1][r], dynamic[i][j] * inv_factorial[k]);
            }
        }
    }
    for (int i = 1; i <= limit; i++) {
        answer -= dynamic[i][total] * factorial[limit] % modulus * inv_factorial[limit - i] % modulus * factorial[total] % modulus;
    }
    answer = (modulus + answer % modulus) % modulus;
    cout << answer << endl;
    return 0;
}
